CREATE TABLE operations (
  document_id uuid NOT NULL, rev bigint NOT NULL, op jsonb NOT NULL,
  user_id uuid NOT NULL, client_id text NOT NULL, client_seq bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (document_id, rev),
  UNIQUE (document_id, client_id, client_seq)
) PARTITION BY HASH (document_id);
